"""Isolate chart/module validation from credentials, Docker socket and real clusters."""
import json,os,pathlib,subprocess,uuid
root=pathlib.Path(__file__).resolve().parent.parent;directory=root/'.local'/('stack-infrastructure-'+str(uuid.uuid4()));directory.mkdir(parents=True)
if os.name!='nt':directory.chmod(0o777)
command=['docker','run','--rm','--network','bridge','--read-only','--cap-drop','ALL','--security-opt','no-new-privileges:true','--tmpfs','/tmp:size=128m,mode=1777','--memory','1g','--cpus','2','--pids-limit','128','-e','GOMAXPROCS=2','--mount','type=bind,source='+str(root/'charts')+',target=/src/charts,readonly','--mount','type=bind,source='+str(root/'infra/terraform')+',target=/src/terraform,readonly','--mount','type=bind,source='+str(root/'scripts/stack-infrastructure-probe.py')+',target=/validate.py,readonly','--mount','type=bind,source='+str(directory)+',target=/out','agenttrust-infrastructure:local','python','/validate.py']
result=subprocess.run(command,cwd=root,capture_output=True,text=True,encoding='utf-8',errors='replace',timeout=900);(directory/'container.log').write_text(result.stdout+'\n'+result.stderr,encoding='utf-8');summary=directory/'summary.json';report=json.loads(summary.read_text(encoding='utf-8')) if summary.exists() else {'completed':False};print(json.dumps({'completed':result.returncode==0 and report['completed'],'checks':len(report.get('checks',[])),'validatedResources':report.get('validatedResources'),'clusterContacted':False,'resourcesApplied':False,'reportPath':str(summary)}))
if result.returncode!=0 or not report['completed']:raise SystemExit(1)
